import RNA, sys, random, time

arm = "((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..))))"
target = "(((((....)).((((((....)))..((((.((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).((((..(((....)))(((.((....))(((...)))((....)).)))(((....)))..)))).))))..(((....)))))).((....)))))"

# Solve arm once with a strong init
def solve_arm(init, n_tries=100):
    random.seed(0)
    res,d=RNA.inverse_fold(init, arm)
    if d==0: return res
    best=res;bd=d
    for _ in range(n_tries):
        r=''.join(random.choice('ACGU') for _ in range(len(arm)))
        r2,d2=RNA.inverse_fold(r, arm)
        if d2<bd:
            bd=d2;best=r2
        if d2==0: return r2
    return best

# Build a complementary init for the arm
def comp_init(s):
    st=[];pr={}
    for i,c in enumerate(s):
        if c=='(':st.append(i)
        elif c==')':
            j=st.pop();pr[j]=i;pr[i]=j
    seq=['A']*len(s)
    for i,j in pr.items():
        if i<j: seq[i]='G';seq[j]='C'
    return ''.join(seq)

t0=time.time()
base=solve_arm(comp_init(arm))
print("base:",base,"t:",round(time.time()-t0,1), file=sys.stderr)
m,_=RNA.fold_compound(base).mfe()
print("base mfe==arm:",m==arm, file=sys.stderr)

# Now make 5 distinct variants by changing loop cap motifs.
# Arm has 3 hairpin loops: positions (relative to arm start):
# find them
st=[];pr={}
for i,c in enumerate(arm):
    if c=='(':st.append(i)
    elif c==')':
        j=st.pop();pr[j]=i;pr[i]=j
loops=[]
for i,j in sorted([(k,v) for k,v in pr.items() if k<v]):
    inner=arm[i+1:j]
    if all(c=='.' for c in inner):
        loops.append((i+1,j-1,len(inner)))
print("arm loops:",loops, file=sys.stderr)

# 3 loops, lengths: [4,4,3] (the (...))) is 3-nt, the others 4-nt)
# Wait let me check
tetra_caps=["GAAA","UUCG","GCAA","CUUG","AGGG","UUAU"]
tri_caps=["UUU","GAA","GUA","CUU","AAG"]

variants=[]
cap_combos=[
    ("GAAA","UUCG","UUU"),
    ("UUCG","GCAA","GAA"),
    ("GCAA","CUUG","GUA"),
    ("CUUG","AGGG","CUU"),
    ("UUAU","GAAA","AAG"),
]
for combo in cap_combos:
    v=list(base)
    for (lo,ro,ll),cap in zip(loops,combo):
        for k,c in enumerate(cap):
            v[lo+k]=c
    v=''.join(v)
    m,_=RNA.fold_compound(v).mfe()
    ok=(m==arm)
    print("combo",combo,"ok",ok, file=sys.stderr)
    if ok:
        variants.append(v)
    else:
        # try to repair by inverse_fold warm-start
        r2,d2=RNA.inverse_fold(v, arm)
        m2,_=RNA.fold_compound(r2).mfe()
        if m2==arm:
            variants.append(r2)
            print("  repaired", file=sys.stderr)
print("nvariants:",len(variants), file=sys.stderr)
for v in variants:
    print("V",v)
sys.stderr.flush()

